head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > titleDivTag]<br/>Accordion 컴포넌트의 패널 타이틀 텍스트를 감싸는 HTML 태그를 div 태그로 변경할지 설정합니다.",
    "validation" : [
        "titleDivTag 속성으로 Accordion 컴포넌트의 패널 타이틀 텍스트를 감싸는 HTML 태그를 div 태그로 변경할지 설정합니다.",
        "true 설정 시 패널 타이틀 텍스트가 'div' 태그로 감싸집니다.",
        "false (default) 설정 시 패널 타이틀 텍스트가 'span' 태그로 감싸집니다.",
        "accessibility=true 인 경우 titleDivTag 속성값과 관계없이 패널 타이틀 텍스트가 항상 'strong' 태그로 감싸집니다.",
        "값을 생략하면 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (createCList 가 빈 문자열을 필터링하여 미설정(생략) 케이스를 표현)
    let properties = {
        titleDivTag : con_titleDivTag.getText(),
        accessibility : con_accessibility.getText(),
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onpanelload", "onpanelunload"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* titleDivTag : 패널 타이틀 텍스트를 감싸는 HTML 태그 설정. true → div, false(default) → span"', '', 'label1');
    $c.gcm.createLabel('label="* accessibility=true 인 경우 titleDivTag 값과 무관하게 항상 strong 태그가 적용됩니다."', '', 'label2');
    $c.gcm.createLabel('label="* [panelTitle 태그 확인] 버튼으로 panels1 의 panelTitle 텍스트 wrapper 태그명을 확인하세요."', '', 'label3');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:240px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onpanelload 핸들러
scwin.target1_onpanelload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelload 이벤트 발생]");
};



// onpanelunload 핸들러
scwin.target1_onpanelunload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelunload 이벤트 발생]");
};



// panelTitle 텍스트를 감싸는 HTML 태그 확인 → div / span / strong 중 어떤 태그가 적용되었는지 출력
// 엔진 initPanelTitle : accessibility(senseReader)=true → strong, titleDivTag=true → div, else → span
scwin.btn_getPanelTitleTag_onclick = function (e) {
    let labelEl1 = target1.render.querySelector("[id$='_panel_panels1_panelTitle_panelTitle1']");
    let labelEl2 = target1.render.querySelector("[id$='_panel_panels2_panelTitle_panelTitle2']");
    wf_body_bottom.getObj("scwin").setReturnValue("panelTitle1 wrapper : " + (labelEl1 ? labelEl1.tagName.toLowerCase() : "null"));
    wf_body_bottom.getObj("scwin").setReturnValue("panelTitle2 wrapper : " + (labelEl2 ? labelEl2.tagName.toLowerCase() : "null"));
};



// 현재 열린 패널 정보 출력 (getOpenPanelListInfo)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
